def check(ctx):
    channel = ctx['channel']
    gross_rental_income = ctx['gross_rental_income']
    pitia = ctx['pitia']
    product_is_interest_only = ctx['product_is_interest_only']
    listed_for_sale_last_6_months = ctx['listed_for_sale_last_6_months']

    missing = rules_lib.gaps(
        channel=channel,
        gross_rental_income=gross_rental_income,
        pitia=pitia,
        product_is_interest_only=product_is_interest_only,
        listed_for_sale_last_6_months=listed_for_sale_last_6_months,
    )
    if missing:
        return rules_lib.unknown(*missing)

    if rules_lib.same(product_is_interest_only, True, 'yes'):
        return rules_lib.unknown('DSCR denominator for interest-only loan (Q-21)')

    dscr = rules_lib.ratio(gross_rental_income, pitia)
    if dscr is None:
        return rules_lib.unknown('gross_rental_income', 'pitia')

    if rules_lib.same(channel, 'correspondent'):
        minimum = 1.2
    elif rules_lib.same(channel, 'wholesale'):
        minimum = 1.0
    else:
        return False

    if rules_lib.same(listed_for_sale_last_6_months, True, 'yes'):
        minimum = max(minimum, 1.0)

    return dscr >= minimum

