def check(ctx):
    property_type = ctx['property_type']
    rural_property = ctx['rural_property']
    missing = rules_lib.gaps(property_type=property_type, rural_property=rural_property)
    if missing:
        return rules_lib.unknown(*missing)

    if rural_property is True or rules_lib.same(rural_property, 'yes', 'true', 'rural'):
        return False
    if rural_property is not False and not rules_lib.same(rural_property, 'no', 'false', 'non-rural'):
        return rules_lib.unknown('rural_property')

    kind = rules_lib.match(property_type, (
        'SFR', 'Townhome', 'PUD', 'Warrantable Condo', 'Two-Units',
        'Rural Property', 'Condotel', 'Condotels', 'Non-Warrantable Condo',
        'Non-Warrantable Condos', 'Short-Term Rental', 'Short-Term Rental (STR)', 'STR'
    ))
    if kind in ('Rural Property', 'Condotel', 'Condotels', 'Non-Warrantable Condo',
                'Non-Warrantable Condos', 'Short-Term Rental', 'Short-Term Rental (STR)', 'STR'):
        return False
    if kind is None:
        return rules_lib.unknown('property_type')

    if kind in ('Two-Units', 'Warrantable Condo'):
        cltv_pct = ctx['cltv_pct']
        missing = rules_lib.gaps(cltv_pct=cltv_pct)
        if missing:
            return rules_lib.unknown(*missing)
        return cltv_pct <= 75.00

    return True

