def check(ctx):
    fico = ctx['fico']
    loan_amount = ctx['loan_amount']
    loan_purpose = ctx['loan_purpose']
    cltv_pct = ctx['cltv_pct']
    channel = ctx['channel']

    missing = rules_lib.gaps(
        fico=fico,
        loan_amount=loan_amount,
        loan_purpose=loan_purpose,
        cltv_pct=cltv_pct,
        channel=channel,
    )
    if missing:
        return rules_lib.unknown(*missing)

    if fico < 700 or loan_amount > 2000000:
        return False

    if rules_lib.same(loan_purpose, 'purchase'):
        max_cltv = 80
    elif rules_lib.same(loan_purpose, 'rate & term', 'rate term'):
        max_cltv = 80
    elif rules_lib.same(loan_purpose, 'cash-out', 'cash out'):
        max_cltv = 75
    else:
        return rules_lib.unknown('loan_purpose')

    if loan_amount < 350000 or loan_amount > 1500000:
        max_cltv = min(max_cltv, 75)

    if rules_lib.same(channel, 'correspondent') and 700 <= fico <= 719:
        max_cltv = min(max_cltv, 60)

    return cltv_pct <= max_cltv

