def check(ctx):
    channel = ctx['channel']
    fico = ctx['fico']
    loan_purpose = ctx['loan_purpose']
    cltv_pct = ctx['cltv_pct']
    loan_amount = ctx['loan_amount']
    property_type = ctx['property_type']
    residential_unit_count = ctx['residential_unit_count']
    listed_for_sale_last_6_months = ctx['listed_for_sale_last_6_months']

    missing = rules_lib.gaps(
        channel=channel,
        fico=fico,
        loan_purpose=loan_purpose,
        cltv_pct=cltv_pct,
        loan_amount=loan_amount,
        property_type=property_type,
        residential_unit_count=residential_unit_count,
        listed_for_sale_last_6_months=listed_for_sale_last_6_months,
    )
    if missing:
        return rules_lib.unknown(*missing)

    if rules_lib.same(loan_purpose, 'purchase'):
        purpose_index = 0
    elif rules_lib.same(loan_purpose, 'rate & term'):
        purpose_index = 1
    elif rules_lib.same(loan_purpose, 'cash-out'):
        purpose_index = 2
    else:
        return False

    base_caps = None
    if rules_lib.same(channel, 'matrix'):
        if fico >= 730:
            base_caps = (80, 80, 75)
        elif 721 <= fico <= 729:
            base_caps = (80, 80, 65)
        elif 700 <= fico <= 720:
            base_caps = (80, 80, 55)
    elif rules_lib.same(channel, 'correspondent'):
        if 700 <= fico <= 719:
            base_caps = (60, 60, 60)

    if base_caps is None:
        return False

    caps = [base_caps[purpose_index]]
    if loan_amount < 350000 or loan_amount > 1500000:
        caps.append(75.00)
    if rules_lib.same(property_type, 'Warrantable Condo'):
        caps.append(75.00)
    if residential_unit_count == 2:
        caps.append(75.00)
    if listed_for_sale_last_6_months:
        caps.append(65)

    return cltv_pct <= min(caps)

