def check(ctx):
    loan_amount = ctx['loan_amount']
    fico = ctx['fico']
    loan_purpose = ctx['loan_purpose']
    cltv_pct = ctx['cltv_pct']
    missing = rules_lib.gaps(loan_amount=loan_amount, fico=fico, loan_purpose=loan_purpose, cltv_pct=cltv_pct)
    if missing:
        return rules_lib.unknown(*missing)

    if loan_amount > 1500000:
        return rules_lib.unknown('CLTV limit for this loan-amount tier')

    transaction = rules_lib.match(loan_purpose, ('purchase', 'rate & term', 'cash-out'))
    if transaction is None:
        return False

    limits = {
        780: {'purchase': 85, 'rate & term': 80, 'cash-out': 80},
        760: {'purchase': 85, 'rate & term': 80, 'cash-out': 80},
        740: {'purchase': 85, 'rate & term': 80, 'cash-out': 80},
        720: {'purchase': 85, 'rate & term': 80, 'cash-out': 80},
        700: {'purchase': 80, 'rate & term': 80, 'cash-out': 75},
        680: {'purchase': 80, 'rate & term': 75, 'cash-out': 75},
        660: {'purchase': 80, 'rate & term': 75, 'cash-out': 75},
        640: {'purchase': 75, 'rate & term': 70, 'cash-out': 70},
        620: {'purchase': 65, 'rate & term': 65, 'cash-out': 65},
        600: {'purchase': 60, 'rate & term': 60, 'cash-out': 60},
    }
    thresholds = (780, 760, 740, 720, 700, 680, 660, 640, 620, 600)
    for threshold in thresholds:
        if fico >= threshold:
            return cltv_pct <= limits[threshold][transaction]
    return False

