def check(ctx):
    citizenship_type = ctx['citizenship_type']
    missing = rules_lib.gaps(citizenship_type=citizenship_type)
    if missing:
        return rules_lib.unknown(*missing)

    if rules_lib.same(citizenship_type, 'US Citizen', 'Permanent Resident', 'Non-Permanent Resident'):
        # The required document checks are not represented by available context fields.
        return True

    if rules_lib.same(citizenship_type, 'Foreign National'):
        fico = ctx['fico']
        cltv_pct = ctx['cltv_pct']
        loan_purpose = ctx['loan_purpose']
        missing = rules_lib.gaps(fico=fico, cltv_pct=cltv_pct, loan_purpose=loan_purpose)
        if missing:
            return rules_lib.unknown(*missing)
        if fico != 700:
            return False
        if rules_lib.same(loan_purpose, 'purchase'):
            return cltv_pct <= 70
        if rules_lib.same(loan_purpose, 'refinance', 'rate and term', 'cash out'):
            return cltv_pct <= 65
        return False

    if rules_lib.same(citizenship_type, 'ITIN'):
        loan_amount = ctx['loan_amount']
        fico = ctx['fico']
        cltv_pct = ctx['cltv_pct']
        loan_purpose = ctx['loan_purpose']
        missing = rules_lib.gaps(loan_amount=loan_amount, fico=fico, cltv_pct=cltv_pct, loan_purpose=loan_purpose)
        if missing:
            return rules_lib.unknown(*missing)
        if loan_amount > 1000000 or fico < 640:
            return False
        if rules_lib.same(loan_purpose, 'purchase'):
            if fico == 700:
                return cltv_pct <= 70
            if 660 <= fico <= 699:
                return cltv_pct <= 65
            if 640 <= fico <= 659:
                return cltv_pct <= 60
            return False
        if rules_lib.same(loan_purpose, 'refinance', 'rate and term', 'cash out'):
            if fico == 700:
                return cltv_pct <= 65
            if 660 <= fico <= 699:
                return cltv_pct <= 60
            if 640 <= fico <= 659:
                return cltv_pct <= 60
            return False
        return False

    return False

